                    print(f"Took {item['id']}: class {item['class']}, weight {item['weight']}, value {item['value']}. Total weight: {current_weight}")
                except Exception as e:
                    print(f"Failed to take {item['id']}: {e}")

# Process the remaining 20 items (from index 20 to 40)
process_batch(to_inspect[20:40])
